function UploadZone({onUpload,notify}){
  const[dragging,setDragging]=useState(false),[uploading,setUploading]=useState(false),[confirmation,setConfirmation]=useState(null),[linked,setLinked]=useState(null),[queued,setQueued]=useState([]);
  async function upload(files){
    if(!files.length)return notify('Solo se aceptan archivos PDF.');
    setUploading(true);setLinked(null);
    for(const [index,file] of files.entries()){const formData=new FormData();formData.append('file',file);
      try{const res=await fetch('/api/imports/upload',{method:'POST',body:formData});const data=await res.json();if(!res.ok)throw new Error(data.error||`Error ${res.status}`);
        if(data.status==='Confirmación requerida'){setConfirmation(data);setQueued(files.slice(index+1));break;}
        if(data.contractId)setLinked(data);
        notify(data.status==='Omitido'?`${data.filename}: ${data.reason}`:data.status==='Revisión'?`${data.filename}: listo para revisar.`:`${data.filename}: ${data.status}`);
      }catch(error){notify(`${file.name}: ${error.message}`);}
    }
    setUploading(false);onUpload({silent:true});
  }
  function cancelReimport(){if(uploading)return;const remaining=queued;setQueued([]);setConfirmation(null);if(remaining.length)upload(remaining);}
  async function reimport(){let remaining=[];setUploading(true);try{const ref=confirmation.importId?{import_id:confirmation.importId}:{document_id:confirmation.documentId};const result=await post('document-admin/reprocess',{ref,confirm:true});setConfirmation(null);remaining=queued;setQueued([]);notify(result.status==='Revisión'?'Documento listo para revisar en Importaciones.':result.error||result.status);onUpload({silent:true});}catch(error){notify(error.message);}finally{setUploading(false);}if(remaining.length)upload(remaining);}
  return <><div className={`upload-zone${dragging?' dragging':''}${uploading?' uploading':''}`} onDragOver={e=>{e.preventDefault();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();e.stopPropagation();setDragging(false);if(!uploading&&!confirmation)upload(Array.from(e.dataTransfer.files).filter(f=>/\.pdf$/i.test(f.name)));}}><div className="upload-zone-body"><Icon name="upload" size={24}/><h3>Arrastra archivos aquí</h3><p>PDF de contratos</p><label className="button secondary">Seleccionar PDF<input type="file" accept="application/pdf" hidden disabled={uploading||Boolean(confirmation)} onChange={e=>{upload(Array.from(e.target.files||[]));e.target.value='';}}/></label>{uploading&&<p className="upload-zone-status">Subiendo...</p>}</div></div>
    {linked&&<p role="status">Este documento ya está asociado a un contrato existente. <a href={`#contracts?contract=${linked.contractId}`}>Abrir contrato {linked.contractCode}</a></p>}
    <ReimportConfirmation document={confirmation} busy={uploading} onClose={cancelReimport} onConfirm={reimport}/></>;
}
function ImportRetryButton({row,actions}){
  const[open,setOpen]=useState(false),[busy,setBusy]=useState(false);
  async function run(){setBusy(true);try{const result=await post('document-admin/reprocess',{ref:{import_id:row.id},confirm:true});actions.notify(result.status==='Revisión'?'Documento listo para revisar en Importaciones.':result.error||result.status);setOpen(false);actions.reload({silent:true});}catch(error){actions.notify(error.message);}finally{setBusy(false);}}
  return <><button type="button" className="button small primary" disabled={busy} onClick={()=>row.status==='Revertido'?setOpen(true):run()}>{row.status==='Error'?'Reintentar importación':'Volver a importar'}</button><ReimportConfirmation document={open?row:null} busy={busy} onClose={()=>setOpen(false)} onConfirm={run}/></>;
}


const reviewDefaults=row=>{const parsed=row?.result_json?.parsed||{},owner=parsed.owners?.[0]||{},tenant=(parsed.tenants?.[0]||parsed.tenant)||{},guarantee=parsed.guarantee||{},resolution=row?.result_json?.entity_resolution||{},propertyCandidate=resolution.property?.candidates?.[0];return{property_id:propertyCandidate?.match==='EXACT_MATCH'?propertyCandidate.id:'',alias:parsed.alias||'',address:parsed.address||'',property_type:parsed.propertyType||'Departamento',rental_type:parsed.rentalType||'Residencial',owner_full_name:owner.fullName||'',owner_document_number:owner.documentNumber||'',tenant_full_name:tenant.fullName||'',tenant_document_number:tenant.documentNumber||'',start_date:parsed.startDate||'',end_date:parsed.endDate||'',duration_months:parsed.durationMonths||'',initial_amount:parsed.initialAmount??'',deposit_amount:parsed.depositAmount??'',currency:parsed.currency||'ARS',adjustment_type:parsed.adjustmentType??parsed.adjustmentIndex??null,adjustment_value_pct:parsed.adjustmentValuePct??'',ipc_lag_months:parsed.ipcLagMonths||0,adjustment_frequency_months:parsed.adjustmentFrequencyMonths||'',adjustment_index:parsed.adjustmentIndex??null,notes:parsed.contractNotes??'',payment_period_start_day:parsed.paymentPeriodStartDay??'',payment_period_end_day:parsed.paymentPeriodEndDay??'',payment_due_day:parsed.paymentDueDay??'',bank_name:parsed.bankName||'',cbu:parsed.cbu||'',late_fee_type:parsed.lateFee?.type||'NONE',late_fee_daily_pct:parsed.lateFee?.dailyPercentage??'',prepaid_rent_months:parsed.paymentTerms?.prepaidRentMonths||'',vat_applicable:parsed.vat?.applicable||false,vat_percentage:parsed.vat?.percentage||'',guarantee_type:guarantee.type||'Otra',guarantee_provider:guarantee.provider||'Otra',guarantee_provider_detail:guarantee.providerDetail||''};};

const IMPORT_STATUS_LABELS={Procesado:'Importado',Revertido:'Contrato eliminado',Error:'Fallido',Omitido:'Omitido por duplicado'};
function ArchivedToggle({rows,checked,onChange,label='Mostrar archivados'}){const total=rows.filter(row=>row.archived_at).length;if(!total)return null;return <label className="archived-toggle"><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)}/>{label} ({total})</label>}
async function toggleArchived(resource,row,label,{reload,notify}){const archived=Boolean(row.archived_at);if(!archived&&!confirm(`¿Archivar «${label}»?\n\nSe oculta de los listados sin borrar nada. Podés restaurarlo cuando quieras.`))return;try{await post(`${resource}/${row.id}/${archived?'restore':'archive'}`,{reason:archived?'Restaurado desde el listado':'Archivado desde el listado'});notify(archived?`«${label}» se restauró.`:`«${label}» se archivó.`);reload({silent:true});}catch(error){notify(error.message);}}
function ReviewSection({title,children}){return <section className="review-section"><h3>{title}</h3><div className="form-grid">{children}</div></section>}
function CandidateList({title,resolution}){const candidates=resolution?.candidates||[];return <div className="candidate-box full"><strong>{title}</strong>{!candidates.length?<span>No hay coincidencias claras en la base. Si confirmás, se crea con los datos detectados.</span>:<ul>{candidates.map(candidate=><li key={candidate.id}><b>{candidate.address||candidate.full_name}</b><span>{{EXACT_MATCH:'Coincidencia exacta',PROBABLE_MATCH:'Posible coincidencia',AMBIGUOUS_MATCH:'Requiere revisión'}[candidate.match]||'Requiere revisión'} · confianza {Math.round((candidate.score||1)*100)}%</span></li>)}</ul>}</div>}

function ImportReviewModal({row,onClose,onSaved,notify}){const[saving,setSaving]=useState(false),[form,setForm]=useState(reviewDefaults(row)),[livePreview,setLivePreview]=useState(null);useEffect(()=>{setForm(reviewDefaults(row));setLivePreview(null);},[row]);useEffect(()=>{if(!row)return;let active=true;const timer=setTimeout(()=>{post('ipc/preview',form).then(value=>{if(active)setLivePreview(value);}).catch(()=>{if(active)setLivePreview(null);});},300);return()=>{active=false;clearTimeout(timer);};},[row,form]);if(!row)return null;const draft=row.result_json||{},parsed=draft.parsed||{},missing=draft.blocking_fields||draft.missing_fields||[],warnings=draft.warnings||row.warnings||[],resolution=draft.entity_resolution||{},preview=livePreview||draft.preview||[];const propertyOptions=[['','Crear nueva / no asociar'],...(resolution.property?.candidates||[]).map(candidate=>[candidate.id,candidate.address])];const change=event=>{const{name,value,type,checked}=event.target;setForm(current=>({...current,[name]:type==='checkbox'?checked:value}));};async function submit(event){event.preventDefault();setSaving(true);try{validateUpdateTerms(form);await post(`imports/${row.id}/complete`,form);await onSaved({silent:true});notify('Contrato confirmado y creado.');onClose();}catch(error){notify(error.message);}finally{setSaving(false);}}return <Modal open title="Revisar importación de contrato" subtitle="Borrador generado a partir del PDF" onClose={onClose} footer={<><button className="button secondary" type="button" onClick={onClose}>Cancelar</button><button className="button primary" form="import-review-form" disabled={saving}>{saving?'Confirmando…':'Confirmar y crear contrato'}</button></>}><div className={`notice compact ${missing.length?'':'success'}`}><b aria-hidden="true">{missing.length?'!':'✓'}</b><div><strong>{missing.length?'Faltan datos bloqueantes':'Listo para confirmar'}</strong><span>{missing.length?missing.map(item=>item.label).join(', '):'El PDF fue analizado. Revisá las entidades y confirmá cuando esté correcto.'}</span></div></div>{warnings.length?<ul className="warnings review-warnings">{warnings.map(item=><li key={item}>{item}</li>)}</ul>:null}<form id="import-review-form" className="review-form" onSubmit={submit}><ReviewSection title="1. Propiedad"><CandidateList title="Coincidencias de propiedad" resolution={resolution.property}/>{resolution.property?.candidates?.length?<FormField label="Asociar propiedad existente" name="property_id" as="select" value={form.property_id} onChange={change} options={propertyOptions}/>:null}<FormField label="Dirección detectada / a crear" name="address" value={form.address} onChange={change} full required/><FormField label="Tipo de inmueble" name="property_type" as="select" value={form.property_type} onChange={change} options={['Departamento','Casa','Local','Oficina','PH','Otro']}/><FormField label="Tipo de alquiler" name="rental_type" as="select" value={form.rental_type} onChange={change} options={['Residencial','Comercial','Profesional','Temporario','Otro']}/></ReviewSection><ReviewSection title="2. Propietarios"><CandidateList title="Coincidencias de propietario" resolution={resolution.owners?.[0]}/><FormField label="Propietario principal" name="owner_full_name" value={form.owner_full_name} onChange={change} required/><FormField label="DNI/CUIT propietario" name="owner_document_number" value={form.owner_document_number} onChange={change} required/><div className="candidate-box full"><strong>Composición</strong><span>Si hay varios propietarios detectados, se conservarán al confirmar. La composición se crea completa al 100% repartida entre titulares detectados.</span>{parsed.owners?.length>1?<ul>{parsed.owners.map(owner=><li key={owner.documentNumber}><b>{owner.fullName}</b><span>{owner.documentNumber}</span></li>)}</ul>:null}</div></ReviewSection><ReviewSection title="3. Inquilinos"><CandidateList title="Coincidencias de inquilino" resolution={resolution.tenants?.[0]}/><FormField label="Inquilino principal" name="tenant_full_name" value={form.tenant_full_name} onChange={change} required/><FormField label="DNI/CUIT inquilino" name="tenant_document_number" value={form.tenant_document_number} onChange={change} required/></ReviewSection><ReviewSection title="4. Vigencia"><FormField label="Alias interno" name="alias" value={form.alias} onChange={change} full/><FormField label="Inicio" name="start_date" type="date" value={form.start_date} onChange={change} required/><FormField label="Finalización" name="end_date" type="date" value={form.end_date} onChange={change}/><FormField label="Duración (meses)" name="duration_months" type="number" min="1" value={form.duration_months} onChange={change} required/></ReviewSection><ReviewSection title="5. Condiciones económicas"><FormField label="Canon inicial" name="initial_amount" type="number" min="0" step="0.01" value={form.initial_amount} onChange={change} required/><FormField label="Depósito" name="deposit_amount" type="number" min="0" step="0.01" value={form.deposit_amount} onChange={change}/><FormField label="Moneda" name="currency" as="select" value={form.currency} onChange={change} options={['ARS','USD','EUR','OTHER']}/><FormField label="Banco" name="bank_name" value={form.bank_name} onChange={change}/><FormField label="CBU" name="cbu" value={form.cbu} onChange={change}/><FormField label="IVA %" name="vat_percentage" type="number" min="0" step="0.01" value={form.vat_percentage} onChange={change}/></ReviewSection><ReviewSection title="6. Ajustes y vencimiento">{parsed.ipcClauseText&&<details className="full"><summary>Cláusula original de ajuste</summary><p>{parsed.ipcClauseText}</p></details>}{parsed.ipcClauseReviewRequired&&<label className="checkbox-line full"><input type="checkbox" checked={Boolean(form.ipc_clause_confirmed)} onChange={event=>setForm(current=>({...current,ipc_clause_confirmed:event.target.checked}))}/><span>Revisé la cláusula ambigua y confirmo los parámetros ingresados.</span></label>}<AdjustmentFields key={row.id} form={form} onChange={patch=>setForm(current=>({...current,...patch}))}/><PaymentScheduleFields key={`payment-${row.id}`} form={form} onChange={patch=>setForm(current=>({...current,...patch}))} periodFields/></ReviewSection><ReviewSection title="7. Punitorios, garantía y pagos iniciales"><LateFeeFields form={form} onChange={patch=>setForm(current=>({...current,...patch}))}/><FormField label="Alquiler anticipado (meses)" name="prepaid_rent_months" type="number" min="0" value={form.prepaid_rent_months} onChange={change}/><FormField label="Tipo de respaldo" name="guarantee_type" as="select" value={form.guarantee_type} onChange={change} options={['Seguro de caución','Garantía propietaria','Sin garantía','Otra']}/><FormField label="Empresa / proveedor" name="guarantee_provider" as="select" value={form.guarantee_provider} onChange={change} options={['Respaldar','Argenprop','Otra']}/><FormField label="Detalle garantía" name="guarantee_provider_detail" value={form.guarantee_provider_detail} onChange={change} full/></ReviewSection>{form.adjustment_index==='IPC'&&preview.length?<ReviewSection title="8. Vista previa de alquileres">{preview.map(item=><div className="rent-preview" key={item.period}><strong>{item.period}</strong><span>{item.note||money(item.amount,item.currency)}</span></div>)}</ReviewSection>:null}</form></Modal>}

function ImportsPanel({rows,reload,notify,columns}){const processed=rows.filter(row=>row.status==='Procesado').length,review=rows.filter(row=>row.status==='Revisión').length,errors=rows.filter(row=>row.status==='Error').length,lastImport=rows[0]?.created_at,previousCount=useRef(rows.length);useEffect(()=>{const timer=setInterval(()=>{reload({silent:true});},6000);return()=>clearInterval(timer);},[reload]);useEffect(()=>{if(rows.length>previousCount.current){const delta=rows.length-previousCount.current;notify(`Se detectó${delta===1?'':'n'} ${delta} contrato${delta===1?'':'s'} nuevo${delta===1?'':'s'} en la carpeta.`);}previousCount.current=rows.length;},[rows,notify]);return <div className="imports-page"><section className="imports-hero card"><div><p className="eyebrow">Centro documental</p><h2>Importaciones de contratos</h2><p>Acá vas a concentrar la entrada de PDFs, los resultados del parser y los casos que requieren revisión manual.</p><div className="imports-stats"><article><strong>{rows.length}</strong><span>Lecturas registradas</span></article><article><strong>{processed}</strong><span>Procesadas</span></article><article><strong>{review}</strong><span>En revisión</span></article><article><strong>{errors}</strong><span>Con error</span></article></div></div><aside className="imports-side"><UploadZone onUpload={reload} notify={notify}/><div className="imports-note"><strong>Última actividad</strong><span>{lastImport?shortDate(lastImport):'Todavía no hay lecturas registradas.'}</span></div><div className="imports-note"><strong>¿Un PDF figura como omitido?</strong><span>En <a href="#documents">Documentos</a> ves el motivo y podés volver a importarlo, excluirlo o eliminarlo.</span></div></aside></section><DataTable columns={columns} rows={rows} className="imports-table" empty="Todavía no hay importaciones" /></div>;}

function PropertyMetric({tone,label,value,icon}){return <article className={`property-metric ${tone||''}`.trim()}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></article>}
function propertyStatus(row){return row.status==='Alquilada'||Number(row.active_contracts)>0?'Ocupado':'Libre'}
function PropertiesPanel({rows,onCreate,reload,notify}){const[search,setSearch]=useState(''),[sort,setSort]=useState('address'),[showArchived,setShowArchived]=useState(false),[deleting,setDeleting]=useState(null);const summary=useMemo(()=>{const total=rows.length,occupied=rows.filter(row=>propertyStatus(row)==='Ocupado').length,free=total-occupied;return{total,occupied,free,rate:total?Math.round((occupied/total)*100):0};},[rows]);const shown=useMemo(()=>rows.filter(row=>(showArchived||!row.archived_at)&&JSON.stringify(row).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>String(a[sort]||'').localeCompare(String(b[sort]||''),'es')),[rows,search,sort,showArchived]);return <div className="properties-page"><header className="properties-heading"><div><h2>Propiedades</h2></div></header><div className="properties-commandbar"><button className="button primary big-action" onClick={onCreate}>+ Nueva propiedad</button></div><section className="occupancy-card card"><h3>Resumen de ocupación</h3><div className="property-metrics"><PropertyMetric icon="⌂" label="Total Propiedades" value={summary.total}/><PropertyMetric icon="♙" tone="success" label="Ocupadas" value={summary.occupied}/><PropertyMetric icon="⌂" label="Libres" value={summary.free}/><PropertyMetric icon="↗" tone="warning" label="Tasa de ocupación" value={`${summary.rate}%`}/></div></section><section className="properties-table-card card"><div className="property-toolbar"><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar propiedad..." aria-label="Buscar propiedad"/><select value={sort} onChange={event=>setSort(event.target.value)} aria-label="Ordenar propiedades"><option value="address">Dirección</option><option value="city">Ciudad</option><option value="province">Provincia</option><option value="status">Estado</option></select><ArchivedToggle rows={rows} checked={showArchived} onChange={setShowArchived} label="Mostrar archivadas"/></div><p className="properties-count">Mostrando {shown.length} de {rows.length} propiedades</p><div className="properties-table-scroll"><table className="properties-table"><thead><tr><th>Dirección</th><th>Ciudad/Barrio</th><th>Provincia</th><th>Contrato</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{shown.map(row=>{const status=propertyStatus(row);return <tr key={row.id} className={row.archived_at?'row-archived':undefined}><td><strong>{row.address}</strong>{row.owners&&<small>{row.owners}</small>}</td><td>{row.city||row.neighborhood||'—'}</td><td>{row.province||'—'}</td><td>{row.active_contract_code||row.active_contract_alias?<><a href="#contracts">{row.active_contract_alias||row.active_contract_code}</a>{row.active_tenant&&<small>{row.active_tenant}</small>}</>:<span className="muted">—</span>}</td><td><span className={`property-status ${status==='Ocupado'?'occupied':'free'}`}>{status}</span>{row.active_tenant&&<small>{row.active_tenant}</small>}{row.archived_at&&<small>Archivada</small>}</td><td><div className="row-actions"><button className="button small secondary" type="button" onClick={()=>toggleArchived('properties',row,row.address,{reload,notify})}>{row.archived_at?'Restaurar':'Archivar'}</button><button className="button small danger" type="button" onClick={()=>setDeleting({resource:'properties',id:row.id,noun:'propiedad'})}>Eliminar</button></div></td></tr>})}</tbody></table></div><ImpactModal target={deleting} onClose={()=>setDeleting(null)} onDone={()=>reload({silent:true})} notify={notify}/>{!shown.length&&<div className="empty"><strong>No encontramos propiedades</strong><span>Probá con otra búsqueda o creá una nueva propiedad.</span></div>}</section></div>}

const OWNER_PROPERTIES_PREVIEW=3;
function OwnerProperties({owner,expanded}){const list=Array.isArray(owner.properties_list)?owner.properties_list:[];if(!list.length)return <span className="muted">Sin propiedades</span>;const visible=expanded?list:list.slice(0,OWNER_PROPERTIES_PREVIEW),hidden=list.length-visible.length;return <div className="owner-properties">{visible.map(property=><span key={property.id} className="owner-property-chip" title={property.code?`${property.address} · ${property.code}`:property.address}>{property.address}</span>)}{hidden>0&&<span className="owner-property-more">+{hidden} más</span>}</div>}
function OwnersPanel({rows,onCreate,onEdit,reload,notify}){const[expanded,setExpanded]=useState(null),[showArchived,setShowArchived]=useState(false),[deleting,setDeleting]=useState(null),shown=rows.filter(owner=>showArchived||!owner.archived_at);return <div className="owners-page"><header className="owners-heading"><h2>Propietarios</h2><p>Personas y empresas titulares asociadas a la cartera de inmuebles.</p></header><div className="properties-commandbar"><button className="button primary big-action" onClick={onCreate}>+ Nuevo propietario</button><ArchivedToggle rows={rows} checked={showArchived} onChange={setShowArchived}/></div><section className="owners-table-card card"><div className="owners-table-scroll"><table className="owners-table"><thead><tr><th>Nombre</th><th>Email</th><th>Propiedades</th><th>Acciones</th></tr></thead><tbody>{shown.map(owner=><tr key={owner.id} className={owner.archived_at?'row-archived':undefined}><td><div className="owner-cell"><strong>{owner.full_name}</strong>{owner.archived_at&&<small>Archivado</small>}<small>{owner.person_kind==='COMPANY'?'Empresa':'Persona'}{owner.document_number?` · ${owner.document_type||'DNI'} ${owner.document_number}`:''}{owner.tax_id?` · CUIT ${owner.tax_id}`:''}</small>{expanded===owner.id&&<div className="owner-details"><span>Teléfono: {owner.phone||'—'}</span><span>WhatsApp: {owner.whatsapp||'—'}</span><span>IVA: {owner.vat_condition||'—'}</span><span>Aviso por correo: {owner.liquidation_email_enabled?'Activo':'Inactivo'}</span><span>Propiedades: {owner.properties_count||0}</span></div>}</div></td><td>{owner.email||'—'}</td><td><OwnerProperties owner={owner} expanded={expanded===owner.id}/></td><td><div className="owner-actions"><button className="button small secondary" type="button" onClick={()=>setExpanded(expanded===owner.id?null:owner.id)}>{expanded===owner.id?'Ocultar':'Ver datos'}</button><button className="button small secondary" type="button" onClick={()=>onEdit(owner)}>Editar</button><button className="button small secondary" type="button" onClick={()=>toggleArchived('owners',owner,owner.full_name,{reload,notify})}>{owner.archived_at?'Restaurar':'Archivar'}</button><button className="button small danger" type="button" onClick={()=>setDeleting({resource:'owners',id:owner.id,noun:'propietario'})}>Eliminar</button></div></td></tr>)}</tbody></table></div><ImpactModal target={deleting} onClose={()=>setDeleting(null)} onDone={()=>reload({silent:true})} notify={notify}/>{!shown.length&&<div className="empty"><strong>No hay propietarios cargados</strong><span>Creá propietarios o asociá personas existentes a propiedades.</span></div>}</section></div>}

