function primary(title,subtitle){return <><strong>{title||'—'}</strong>{subtitle&&<small>{subtitle}</small>}</>}
async function discardImport(row,actions){
  if(!confirm(`¿Descartar la importación "${row.filename}"?\n\nNo se creará ningún contrato ni se usará esta lectura.`))return;
  try{await post(`imports/${row.id}/discard`,{reason:'Descartada desde importaciones'});actions.notify('Importación descartada.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
async function revertImport(row,actions){
  if(!confirm(`¿Revertir la importación "${row.filename}"?\n\nSe eliminará el contrato creado, su documento y sus cobros pendientes si no existen pagos registrados. No se borrarán datos compartidos o sin trazabilidad segura.`))return;
  try{await post(`imports/${row.id}/revert`,{reason:'Revertida desde importaciones'});actions.notify('Importación revertida correctamente.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
async function voidContract(row,actions){
  const reason=prompt(`Motivo para anular el contrato ${row.code}:`,'Cargado por error');
  if(reason===null)return;
  if(!confirm(`¿Anular el contrato ${row.code}?\n\nNo se borra información histórica. El contrato dejará de generar cobros pendientes.`))return;
  try{await post(`contracts/${row.id}/void`,{reason});actions.notify('Contrato anulado.');actions.reload({silent:true});}
  catch(error){actions.notify(error.message);}
}
